PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT (?a_writtenRep AS ?writtenRep) ?count
WHERE {
  { SELECT ?a_writtenRep (COUNT(DISTINCT ?a_sense) AS ?count) WHERE {
      SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
        ?a_lexicalEntry ontolex:canonicalForm [ ontolex:writtenRep ?a_writtenRep ] .
        ?a_lexicalEntry ontolex:sense ?a_sense .
        FILTER(regex(str(?a_writtenRep), "^(banco|piano|campo|punto)$", "i")) .
      }
    }
    GROUP BY ?a_writtenRep
  }
  { SELECT (MAX(xsd:float(?count)) AS ?r_value) WHERE {
      { SELECT ?a2_writtenRep (COUNT(DISTINCT ?a2_sense) AS ?count) WHERE {
          SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
            ?a2_lexicalEntry ontolex:canonicalForm [ ontolex:writtenRep ?a2_writtenRep ] .
            ?a2_lexicalEntry ontolex:sense ?a2_sense .
            FILTER(regex(str(?a2_writtenRep), "^(banco|piano|campo|punto)$", "i")) .
          }
        }
        GROUP BY ?a2_writtenRep
      }
    }
  }
  FILTER(STR(?count) = STR(?r_value))
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (?c_writtenRep AS ?writtenRep) (COUNT(DISTINCT ?c_sense) AS ?count)
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?c_lexicalEntry ontolex:canonicalForm [ ontolex:writtenRep ?c_writtenRep ] .
    ?c_lexicalEntry ontolex:sense ?c_sense .
    FILTER(regex(str(?c_writtenRep), "^(capo|fine|corso)$", "i")) .
  }
}
GROUP BY ?c_writtenRep
ORDER BY DESC(?count)

